    mix(-aspect * 1.22, aspect * 1.22, t),
    sin((t * 1.72 - 0.2) * PI) * 0.54 + sin(t * PI * 3.0) * 0.12,
    cos(t * PI * 2.0 - 0.7) * 0.22
